compact/posix/zed/ollama-embed/vllm-llm.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
# Configure ChunkHound with Ollama embeddings and vLLM for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "openai",
    "model": "Qwen/Qwen3-Coder-30B-A3B-Instruct",
    "base_url": "http://localhost:8002/v1"
  }
}
CHUNKHOUND_EOF
# Configure Zed to connect to ChunkHound via MCP.
if [ -f .zed/settings.json ]; then
cat <<'CHUNKHOUND_EOF'
.zed/settings.json already exists — merge this block into it manually:
{
  "context_servers": {
    "chunkhound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
else
mkdir -p .zed
cat > .zed/settings.json <<'CHUNKHOUND_EOF'
{
  "context_servers": {
    "chunkhound": {
      "command": "chunkhound",
      "args": [
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
fi
# Build ChunkHound's search index for this project.
chunkhound index .

